AssistantMessageToolRequest(name='create', tool_call_id='tooluse_2UEymn8KTWwuXd7dvLdCxc', arguments={'file_text': "class ContactForm {
    constructor(formId) {
        this.form = document.getElementById(formId);
        this.fields = {
            fullName: {
                input: document.getElementById('fullName'),
                errorElement: document.getElementById('fullNameError'),
                validate: (value) => this.validateFullName(value)
            },
            email: {
                input: document.getElementById('email'),
                errorElement: document.getElementById('emailError'),
                validate: (value) => this.validateEmail(value)
            },
            phone: {
                input: document.getElementById('phone'),
                errorElement: document.getElementById('phoneError'),
                validate: (value) => this.validatePhone(value)
            }
        };

        this.successMessage = document.getElementById('successMessage');
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        Object.keys(this.fields).forEach(fieldName => {
            const field = this.fields[fieldName];
            field.input.addEventListener('blur', () => this.validateField(fieldName));
            field.input.addEventListener('input', () => this.validateField(fieldName));
        });
    }

    validateFullName(value) {
        value = value.trim();

        if (!value) {
            return { valid: false, message: 'Full name is required' };
        }

        if (value.length < 2) {
            return { valid: false, message: 'Full name must be at least 2 characters' };
        }

        if (!/^[a-zA-Z\s'-]+$/.test(value)) {
            return { valid: false, message: 'Full name can only contain letters, spaces, hyphens, and apostrophes' };
        }

        return { valid: true, message: '' };
    }

    validateEmail(value) {
        value = value.trim();

        if (!value) {
            return { valid: false, message: 'Email address is required' };
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(value)) {
            return { valid: false, message: 'Please enter a valid email address' };
        }

        return { valid: true, message: '' };
    }

    validatePhone(value) {
        value = value.trim();

        if (!value) {
            return { valid: true, message: '' };
        }

        const phoneRegex = /^[\s().\-\d]+$/;
        if (!phoneRegex.test(value)) {
            return { valid: false, message: 'Phone number contains invalid characters' };
        }

        const digitsOnly = value.replace(/\D/g, '');
        if (digitsOnly.length < 10 || digitsOnly.length > 15) {
            return { valid: false, message: 'Phone number must contain 10-15 digits' };
        }

        return { valid: true, message: '' };
    }

    validateField(fieldName) {
        const field = this.fields[fieldName];
        const value = field.input.value;
        const result = field.validate(value);

        this.setFieldState(field.input, field.errorElement, result.valid, result.message);
    }

    setFieldState(inputElement, errorElement, isValid, message) {
        inputElement.classList.remove('error', 'success');

        if (!isValid && inputElement.value.trim()) {
            inputElement.classList.add('error');
            errorElement.textContent = message;
        } else if (isValid && inputElement.value.trim()) {
            inputElement.classList.add('success');
            errorElement.textContent = '';
        } else {
            errorElement.textContent = '';
        }
    }

    handleSubmit(e) {
        e.preventDefault();

        let isFormValid = true;
        Object.keys(this.fields).forEach(fieldName => {
            this.validateField(fieldName);
            const field = this.fields[fieldName];
            if (field.input.classList.contains('error')) {
                isFormValid = false;
            }
        });

        if (isFormValid) {
            this.submitForm();
        }
    }

    submitForm() {
        const formData = {
            fullName: this.fields.fullName.input.value.trim(),
            email: this.fields.email.input.value.trim(),
            phone: this.fields.phone.input.value.trim()
        };

        console.log('Form submitted with data:', formData);

        this.form.style.display = 'none';
        this.successMessage.style.display = 'block';

        setTimeout(() => {
            this.form.reset();
            Object.keys(this.fields).forEach(fieldName => {
                const field = this.fields[fieldName];
                field.input.classList.remove('error', 'success');
                field.errorElement.textContent = '';
            });
            this.form.style.display = 'block';
            this.successMessage.style.display = 'none';
        }, 3000);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ContactForm('contactForm');
});
